module ski_probability(\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] ski_prob_01,\n    input [31:0] ski_prob_02,\n    input [31:0] ski_prob_03,\n    input [31:0] ski_prob_12,\n    input [31:0] ski_prob_13,\n    input [31:0] ski_prob_23,\n    input walk_edge_01,\n    input walk_edge_02,\n    input walk_edge_03,\n    input walk_edge_12,\n    input walk_edge_13,\n    input walk_edge_23,\n    output reg [31:0] prob_k0,\n    output reg [31:0] prob_k1,\n    output reg [31:0] prob_k2,\n    output reg [31:0] prob_k3,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] SKI    = 3'd1;\n    localparam [2:0] WALK   = 3'd2;\n    localparam [2:0] NEXT_K = 3'd3;\n    localparam [2:0] FINAL  = 3'd4;\n    localparam [2:0] DONE_ST= 3'd5;\n    \n    // Constants\n    localparam [1:0] MAX_K = 2'd3;\n    localparam [1:0] NODES = 4;\n    \n    // Internal registers\n    reg [2:0] state;\n    reg [1:0] current_k;\n    reg [2:0] edge_count;\n    reg [63:0] temp_product;\n    reg [31:0] dp [0:3][0:3];  // Nodes [0-3], k-steps [0-3]\n    integer i, j;  // Loop counters for initialization\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            current_k <= 2'd0;\n            edge_count <= 3'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                for (j = 0; j < 4; j = j + 1) begin\n                    dp[i][j] <= 32'd0;\n                end\n            end\n            prob_k0 <= 32'd0;\n            prob_k1 <= 32'd0;\n            prob_k2 <= 32'd0;\n            prob_k3 <= 32'd0;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize DP table\n                        for (i = 0; i < 4; i = i + 1) begin\n                            for (j = 0; j < 4; j = j + 1) begin\n                                dp[i][j] <= 32'd0;\n                            end\n                        end\n                        dp[0][0] <= 32'h00010000;  // Q16.16 1.0\n                        current_k <= 2'd0;\n                        edge_count <= 3'd0;\n                        state <= SKI;\n                    end\n                end\n\n                SKI: begin\n                    case(edge_count)\n                        3'd0: if (ski_prob_01 != 32'd0) dp[1][current_k] <= (dp[0][current_k] * ski_prob_01)[47:16];\n                        3'd1: if (ski_prob_02 != 32'd0) dp[2][current_k] <= (dp[0][current_k] * ski_prob_02)[47:16];\n                        3'd2: if (ski_prob_03 != 32'd0) dp[3][current_k] <= (dp[0][current_k] * ski_prob_03)[47:16];\n                        3'd3: if (ski_prob_12 != 32'd0) dp[2][current_k] <= (dp[1][current_k] * ski_prob_12)[47:16];\n                        3'd4: if (ski_prob_13 != 32'd0) dp[3][current_k] <= (dp[1][current_k] * ski_prob_13)[47:16];\n                        3'd5: if (ski_prob_23 != 32'd0) dp[3][current_k] <= (dp[2][current_k] * ski_prob_23)[47:16];\n                    endcase\n                    \n                    if (edge_count == 3'd5) begin\n                        edge_count <= 3'd0;\n                        state <= WALK;\n                    end else begin\n                        edge_count <= edge_count + 3'd1;\n                    end\n                end\n\n                WALK: begin\n                    case(edge_count)\n                        3'd0: if (walk_edge_01 && current_k < MAX_K) begin\n                            if (dp[0][current_k] > dp[1][current_k+1]) dp[1][current_k+1] <= dp[0][current_k];\n                            if (dp[1][current_k] > dp[0][current_k+1]) dp[0][current_k+1] <= dp[1][current_k];\n                        end\n                        3'd1: if (walk_edge_02 && current_k < MAX_K) begin\n                            if (dp[0][current_k] > dp[2][current_k+1]) dp[2][current_k+1] <= dp[0][current_k];\n                            if (dp[2][current_k] > dp[0][current_k+1]) dp[0][current_k+1] <= dp[2][current_k];\n                        end\n                        3'd2: if (walk_edge_03 && current_k < MAX_K) begin\n                            if (dp[0][current_k] > dp[3][current_k+1]) dp[3][current_k+1] <= dp[0][current_k];\n                            if (dp[3][current_k] > dp[0][current_k+1]) dp[0][current_k+1] <= dp[3][current_k];\n                        end\n                        3'd3: if (walk_edge_12 && current_k < MAX_K) begin\n                            if (dp[1][current_k] > dp[2][current_k+1]) dp[2][current_k+1] <= dp[1][current_k];\n                            if (dp[2][current_k] > dp[1][current_k+1]) dp[1][current_k+1] <= dp[2][current_k];\n                        end\n                        3'd4: if (walk_edge_13 && current_k < MAX_K) begin\n                            if (dp[1][current_k] > dp[3][current_k+1]) dp[3][current_k+1] <= dp[1][current_k];\n                            if (dp[3][current_k] > dp[1][current_k+1]) dp[1][current_k+1] <= dp[3][current_k];\n                        end\n                        3'd5: if (walk_edge_23 && current_k < MAX_K) begin\n                            if (dp[2][current_k] > dp[3][current_k+1]) dp[3][current_k+1] <= dp[2][current_k];\n                            if (dp[3][current_k] > dp[2][current_k+1]) dp[2][current_k+1] <= dp[3][current_k];\n                        end\n                    endcase\n                    \n                    if (edge_count == 3'd5) begin\n                        edge_count <= 3'd0;\n                        state <= NEXT_K;\n                    end else begin\n                        edge_count <= edge_count + 3'd1;\n                    end\n                end\n\n                NEXT_K: begin\n                    if (current_k < MAX_K) begin\n                        current_k <= current_k + 2'd1;\n                        state <= SKI;\n                    end else begin\n                        state <= FINAL;\n                    end\n                end\n\n                FINAL: begin\n                    prob_k0 <= dp[3][0];\n                    prob_k1 <= (dp[3][0] > dp[3][1]) ? dp[3][0] : dp[3][1];\n                    prob_k2 <= (prob_k1 > dp[3][2]) ? prob_k1 : dp[3][2];\n                    prob_k3 <= (prob_k2 > dp[3][3]) ? prob_k2 : dp[3][3];\n                    done <= 1'b1;\n                    state <= DONE_ST;\n                end\n\n                DONE_ST: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule